import SwiftUI


// MARK: - Equipped App Theme Color

@MainActor
extension GamificationViewModel {

    var currentAppThemeColor: Color? {

        // Find the equipped app theme
        guard let themeID = equippedCosmeticID(for: "theme") else {
            return nil
        }

        // Look up its details in the cosmetic catalog
        guard let theme = cosmeticCatalog.first(where: {
            $0.id == themeID && $0.cosmetic_type == "theme"
        }) else {
            return nil
        }

        // Choose a color based on its collection
        switch theme.collection {

        case "astral":
            return .purple

        case "nature":
            return .green

        case "cyber":
            return .cyan

        default:
            return nil
        }
    }
}


// MARK: - Shared App Theme Modifier

struct ProjectHealthThemeModifier: ViewModifier {

    @ObservedObject var gamificationViewModel: GamificationViewModel

    func body(content: Content) -> some View {

        content

            // Background with a subtle theme tint
            .background(
                Color(.systemGroupedBackground)
                    .overlay(
                        (
                            gamificationViewModel.currentAppThemeColor
                            ?? .clear
                        )
                        .opacity(0.05)
                    )
                    .ignoresSafeArea()
            )

            // Apply the theme accent to SwiftUI controls
            .tint(
                gamificationViewModel.currentAppThemeColor
            )
    }
}

